mapper.update:
UPDATE after_sales

    state = #{state}

        , actual_refund_amount = #{actualRefundAmount}


        , seller_reply = #{sellerReply}


WHERE order_id = #{orderId}

mapper.select:
SELECT sales.order_id orderId, sales.username, sales.goods_id goodsId, gs.goods_title goodsTitle, gs.goods_desc goodsDesc, gs.goods_img goodsImg, gs.goods_price goodsPrice, od.total_price totalPrice, od.pay_time payTime, od.reservation_start_time reservationStartTime, od.reservation_end_time reservationEndTime, sales.request_refund_amount requestRefundAmount, sales.refund_reason refundReason, sales.actual_refund_amount actualRefundAmount, sales.seller_reply sellerReply, sales.state, sales.create_time createTime FROM after_sales sales LEFT JOIN goods gs on sales.goods_id = gs.goods_id LEFT JOIN `order` od on sales.order_id = od.order_id
username = #{username}
ORDER BY sales.create_time DESC
